<script setup lang="ts">
import {computed,onBeforeUnmount,ref,watch} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {ElMessage,ElMessageBox} from 'element-plus'
import type {Evidence,JsonObject,Material,TaskStatus} from '@/domain/types'
import {toolMap,taskStatusLabels} from '@/domain/tools'
import {service} from '@/services/service'
import {useTaskPolling,activeTaskStates} from '@/composables/useTaskPolling'
import {object,text,displayLabels,evidenceOf} from '@/components/results/model'
import {downloadTask} from '@/components/results/download'
import TaskInfoDialog from '@/components/results/TaskInfoDialog.vue'
import SourcePreview from '@/components/SourcePreview.vue'
import EvidenceLinks from '@/components/results/EvidenceLinks.vue'
import ExtractResults from '@/components/results/ExtractResults.vue'
import ContractReportBar from '@/components/results/ContractReportBar.vue'
import {addSelectedWords} from '@/domain/lexicon'
import WordResults from '@/components/results/WordResults.vue'
import ThemeResults from '@/components/results/ThemeResults.vue'
import TimelineResults from '@/components/results/TimelineResults.vue'
import MeetingResults from '@/components/results/MeetingResults.vue'
import FindingResults from '@/components/results/FindingResults.vue'
import LedgerResults from '@/components/results/LedgerResults.vue'
import PrepaidResults from '@/components/results/PrepaidResults.vue'
const route=useRoute(),router=useRouter(),id=computed(()=>String(route.params.id ?? ''))
const {task,error,loading,refresh}=useTaskPolling(id,(taskId,signal)=>service.getTask(taskId,signal))
const data=computed(()=>object(task.value?.results)),showInfo=ref(false),exporting=ref(false),sourceLoading=ref(false),sourceError=ref(''),sourceVisible=ref(false),sourceFile=ref<Material|null>(null),sourceRef=ref<Evidence>(),detail=ref<JsonObject|null>(null),actionBusy=ref(false)
const tool=computed(()=>task.value?.tool ? toolMap[task.value.tool] : null)
const active=computed(()=>task.value ? activeTaskStates.has(task.value.status) : false)
const supportedResult=computed(()=>{
 const keys:Record<string,string[]>={extract:['rows'],word:['words'],theme:['themes','extractions','summary'],timeline:['events'],meeting:['meetings','clusters','risks','answers'],risk:['findings'],contract:['findings'],bidding:['findings'],prepaid:['agreements','calculations'],engineering:['duplicates','parentChildren'],association:['matches','unmatchedA','unmatchedB','differences']}
 return !!task.value?.tool && (keys[task.value.tool] ?? []).some(key=>Object.prototype.hasOwnProperty.call(data.value,key))
})
const canReanalyze=computed(()=>!!task.value?.tool && !!task.value.draft && task.value.draft.tool===task.value.tool && Array.isArray(task.value.draft.files) && task.value.draft.files.length>0 && !!task.value.draft.config && !!task.value.draft.prompts)
let sourceVersion=0
function clearSource(){sourceVersion++;sourceLoading.value=false;sourceFile.value=null;sourceRef.value=undefined;sourceError.value=''}
watch(sourceVisible,visible=>{if(!visible)clearSource()})
watch(id,()=>{sourceVisible.value=false;clearSource();detail.value=null;showInfo.value=false})
onBeforeUnmount(clearSource)
async function source(evidence:Evidence){
 const version=++sourceVersion
 sourceVisible.value=true;sourceLoading.value=true;sourceError.value='';sourceFile.value=null;sourceRef.value=evidence
 try{
  const existing=task.value?.draft?.files.find(f=>f.id===evidence.fileId) ?? Object.values(task.value?.draft?.attachments ?? {}).flat().find(f=>f.id===evidence.fileId)
  const file=existing ?? (await service.getMaterials([evidence.fileId]))[0] ?? null
  if(version!==sourceVersion)return
  sourceFile.value=file
  if(!file)sourceError.value='未找到此来源资料，可能已被移除或无权访问。'
 }catch(e){if(version===sourceVersion)sourceError.value=e instanceof Error ? e.message : '加载来源失败'}finally{if(version===sourceVersion)sourceLoading.value=false}
}
function reanalyze(excluded?:string){if(!canReanalyze.value || !task.value?.draft || !task.value.tool)return;try{const draft=JSON.parse(JSON.stringify(task.value.draft));draft.sourceTaskId=task.value.id;if(typeof excluded==='string'&&draft.tool==='word')Object.assign(draft.config,addSelectedWords(draft.config.stopWords||[],draft.config.newWords||[],[{word:excluded,kind:'stop'}]));sessionStorage.setItem(`audit:reanalysis:${task.value.tool}`,JSON.stringify(draft));router.push(`/tool/${task.value.tool}`)}catch{ElMessage.error('无法保存再次分析草稿，请检查浏览器存储空间。')}}
async function exportData(format:'excel'|'csv'|'json'|'markdown'){if(!task.value)return;exporting.value=true;try{await downloadTask(task.value,format)}catch(e){ElMessage.error(e instanceof Error ? e.message : '导出失败')}finally{exporting.value=false}}
async function manage(action:'stop'|'retry'){if(!task.value)return;try{await ElMessageBox.confirm(action==='stop' ? '停止后保留已完成结果，是否继续？' : '仅重试当前任务中失败的部分，是否继续？',action==='stop' ? '停止分析' : '重试失败项',{confirmButtonText:'确认',cancelButtonText:'取消'});actionBusy.value=true;await (action==='stop' ? service.stopTask(task.value.id) : service.retryTask(task.value.id));refresh()}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error(e instanceof Error ? e.message : '操作失败')}finally{actionBusy.value=false}}
function statusType(value:TaskStatus):'success'|'warning'|'danger'|'info'|'primary'{return value==='completed' ? 'success' : value==='failed' ? 'danger' : ['partial','awaiting_input'].includes(value) ? 'warning' : activeTaskStates.has(value) ? 'primary' : 'info'}
</script>
<template><main class="result-page" v-loading="loading && !task"><header class="result-heading"><div class="result-title"><el-button text @click="router.push(task?.tool ? `/tool/${task.tool}/history` : '/tasks')">返回记录</el-button><h1>{{tool?.name ?? '分析任务'}}</h1><el-tag v-if="task" :type="statusType(task.status)">{{taskStatusLabels[task.status]}}</el-tag></div><div v-if="task" class="result-actions"><el-tooltip :disabled="canReanalyze" content="服务未返回完整的执行资料与配置快照，暂不能再次分析。"><span><el-button :disabled="!canReanalyze" @click="reanalyze()">再次分析</el-button></span></el-tooltip><el-dropdown @command="exportData"><el-button type="primary" :loading="exporting" :disabled="!task.hasResults || !task.tool">导出</el-button><template #dropdown><el-dropdown-menu><el-dropdown-item command="excel">Excel</el-dropdown-item><el-dropdown-item v-if="service.capabilities.demo || !['engineering','contract'].includes(task.tool ?? '')" command="csv">CSV</el-dropdown-item><el-dropdown-item command="json">JSON</el-dropdown-item><el-dropdown-item v-if="service.capabilities.demo || !['engineering','contract'].includes(task.tool ?? '')" command="markdown">Markdown</el-dropdown-item></el-dropdown-menu></template></el-dropdown></div></header><el-alert v-if="error" :title="error" type="error" :closable="false" show-icon><template #default><el-button text type="primary" @click="refresh">重新加载</el-button><span v-if="task"> 当前保留上次取得的任务状态。</span></template></el-alert><template v-if="task"><div class="task-caption"><span class="task-title">{{task.name}}</span><span>{{task.createdAt}}</span><el-button text type="primary" @click="showInfo=true">任务信息</el-button></div><section v-if="active || ['partial','failed','awaiting_input','stopped','unknown'].includes(task.status)" class="runtime-panel panel"><div><strong>{{task.stage || taskStatusLabels[task.status]}}</strong><p>共 {{task.total}} 份 · 已完成 <b>{{task.completed}}</b> 份<span v-if="task.failed"> · 失败 <b>{{task.failed}}</b> 份</span></p><p v-if="task.error" class="error-text">{{task.error}}</p><p v-if="active" class="muted">可以离开此页，稍后从本工具的分析记录中继续查看。</p></div><el-progress v-if="typeof task.progress==='number'" :percentage="Math.max(0,Math.min(100,task.progress))" :stroke-width="8"/><div class="runtime-actions"><el-button v-if="active && service.capabilities.taskStop" :loading="actionBusy" @click="manage('stop')">停止分析</el-button><el-button v-if="['failed','partial'].includes(task.status) && service.capabilities.taskRetry" :loading="actionBusy" @click="manage('retry')">重试失败项</el-button><el-button @click="refresh">刷新状态</el-button></div></section><section class="panel result-body"><ContractReportBar v-if="task.tool==='contract'" :task="task"/><template v-if="supportedResult"><ExtractResults v-if="task.tool==='extract'" :data="data" @source="source" @detail="detail=$event"/><WordResults v-else-if="task.tool==='word'" :data="data" :top-n="task.draft?.config.topN" :can-refine="canReanalyze" @exclude="reanalyze" @source="source" @detail="detail=$event"/><ThemeResults v-else-if="task.tool==='theme'" :data="data" @source="source" @detail="detail=$event"/><TimelineResults v-else-if="task.tool==='timeline'" :data="data" @source="source" @detail="detail=$event"/><MeetingResults v-else-if="task.tool==='meeting'" :data="data" :task="task" @source="source" @detail="detail=$event" @refresh="refresh"/><FindingResults v-else-if="task.tool==='risk'||task.tool==='contract'||task.tool==='bidding'" :data="data" :tool="task.tool" @source="source" @detail="detail=$event"/><LedgerResults v-else-if="task.tool==='engineering'||task.tool==='association'" :data="data" :task="task" @source="source" @detail="detail=$event" @refresh="refresh"/><PrepaidResults v-else-if="task.tool==='prepaid'" :data="data" :task="task" @source="source" @detail="detail=$event" @refresh="refresh"/></template><template v-else><el-empty :description="active ? '任务正在处理，结果返回后将在此显示' : task.hasResults ? '结果已返回，当前数据结构尚未匹配专用视图' : '尚未返回可查看的分析结果'"/><p class="muted centered">{{task.hasResults ? '可展开服务返回内容或导出原始数据核查，不能据此判断没有审计问题。' : '没有结果不代表没有审计问题，请结合任务状态确认执行情况。'}}</p><el-collapse v-if="task.results && Object.keys(task.results).length"><el-collapse-item title="服务返回内容" name="raw"><pre class="readable-text">{{text(task.results)}}</pre></el-collapse-item></el-collapse></template></section></template><TaskInfoDialog v-model="showInfo" :task="task"/><el-drawer :model-value="!!detail" title="结果详情" size="min(720px, 100vw)" @update:model-value="!$event && (detail=null)"><template v-if="detail"><el-descriptions :column="1" border><el-descriptions-item v-for="(value,key) in detail" :key="key" :label="displayLabels[String(key)] ?? String(key)"><pre class="detail-value">{{text(value)}}</pre></el-descriptions-item></el-descriptions><div class="detail-sources"><EvidenceLinks :evidence="evidenceOf(detail)" @open="source"/></div></template></el-drawer><el-dialog v-model="sourceVisible" title="查看来源" width="min(1200px, calc(100vw - 24px))" class="result-source-dialog" destroy-on-close><div class="source-container" v-loading="sourceLoading"><el-alert v-if="sourceError" :title="sourceError" type="error" :closable="false"/><SourcePreview v-else-if="sourceFile" :file="sourceFile" :evidence="sourceRef" :step="false"/><el-empty v-else-if="!sourceLoading" description="未提供可查看的来源"/></div></el-dialog></main></template>
<style scoped>.result-page{padding:20px 24px;min-width:0;height:100%;overflow:auto}.result-heading{display:flex;justify-content:space-between;align-items:center;gap:16px;flex-wrap:wrap}.result-title{display:flex;align-items:center;gap:12px;min-width:0}.result-title h1{font-size:22px;margin:0}.result-actions{display:flex;gap:12px;align-items:center}.task-caption{display:flex;gap:16px;align-items:center;flex-wrap:wrap;color:#596b80;font-size:14px;margin:8px 0 16px}.task-title{color:#1e3046;font-weight:600}.runtime-panel{display:grid;grid-template-columns:minmax(200px,1fr) minmax(100px,220px) auto;align-items:center;gap:20px;padding:20px;margin:16px 0}.runtime-panel p{margin:8px 0 0;line-height:1.6}.runtime-actions{display:flex;gap:8px;flex-wrap:wrap}.runtime-actions .el-button{margin:0}.result-body{padding:20px;min-width:0}.muted{color:#596b80;font-size:14px}.centered{text-align:center}.error-text{color:#a33e3e}.readable-text,.detail-value{white-space:pre-wrap;overflow-wrap:anywhere;word-break:break-word;font:inherit;line-height:1.7;max-height:500px;overflow:auto}.detail-value{margin:0}.detail-sources{margin-top:16px}.source-container{height:min(70vh,800px);min-height:260px;display:flex;flex-direction:column}.source-container :deep(.source-preview){flex:1;min-height:0}@media(max-width:800px){.result-page{padding:12px}.result-title h1{font-size:20px}.runtime-panel{grid-template-columns:1fr}.result-body{padding:12px}}</style>
